const MODULE_ICON_MAP = {
  checkbox_filter: CheckboxModuleIcon,
  dropdown_filter: DropdownModuleIcon,
  range_slider: RangeModuleIcon,
  search: SearchModuleIcon,
  reset: ResetModuleIcon,
  customtext: CustomTextModuleIcon,
  woo_rating_filter: CheckboxModuleIcon,
};

function FilterModulePickerIcon({ moduleKey, className }) {
  const Icon = MODULE_ICON_MAP[moduleKey] || CheckboxModuleIcon;
  return <Icon className={className} />;
}

export default FilterModulePickerIcon;
